import { inflateRaw } from '../../mol-util/zip/zip';
import { RuntimeContext } from '../../mol-task';

const Area = '';
const Search = '7dNBCsAwCARA9f9/bkmOgVoCLbnMYUAQFBaNiCsAAAAAADgmM6e1fut9ObObvbNXDrgHOcDfqmoa9XqDXa+z+xdjx+m/kAPuQQ5Pbg==';

export async function getSmaaLookupData() {
    const decode = (value: string) => Uint8Array.from(atob(value), c => c.charCodeAt(0));
    const [area, search] = await Promise.all([inflateRaw(RuntimeContext.Synchronous, decode(Area)), inflateRaw(RuntimeContext.Synchronous, decode(Search))]);
    return { area: { width: 160, height: 560, array: area }, search: { width: 66, height: 33, array: search } };
}
